package com.sasch.cameragps.sharednew.remote.wifi

import kotlin.io.encoding.Base64

/** Synthetic 2x2 JPEG produced with ImageIO; contains no camera image data. */
internal fun previewJpegFixture(): ByteArray = Base64.decode(
    ""
)

internal fun previewFrameFixture(): ByteArray {
    val jpeg = previewJpegFixture()
    val header = ByteArray(16)
    listOf(160, jpeg.size + 34, 24, 136).forEachIndexed { index, value ->
        (0..3).forEach { byte -> header[index * 4 + byte] = (value ushr (byte * 8)).toByte() }
    }
    return header + ByteArray(8 + 136) + jpeg + ByteArray(34)
}
